import{_ as a,o as d,c as e,a3 as r}from"./chunks/framework.CWYzGJW1.js";const b=JSON.parse('{"title":"成本試算表","description":"自架與雲端的成本差異主要取決於三個數字: 每月實際用量, 硬體可用年數, 維運人時.","frontmatter":{"description":"自架與雲端的成本差異主要取決於三個數字: 每月實際用量, 硬體可用年數, 維運人時."},"headers":[],"relativePath":"decide/tco.md","filePath":"decide/tco.md","lastUpdated":1793063507000}'),o={name:"decide/tco.md"};function i(l,t,n,s,h,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="成本試算表" tabindex="-1">成本試算表 <a class="header-anchor" href="#成本試算表" aria-label="Permalink to &quot;成本試算表&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本頁屬性</p><ul><li>等級: 決策參考</li><li>狀態: 可閱讀</li><li>資料基準日: 2026-10-27</li><li>實機驗證: 不適用</li></ul></div><p><strong>結論</strong>: 自架與雲端的成本差異主要取決於三個數字: 每月實際用量, 硬體可用年數, 維運人時. 其中維運人時多半估得偏低 (信心: 中, 屬推論). 本頁提供公式與填寫表, 不提供市場價格.</p><div class="tip custom-block"><p class="custom-block-title">本頁是試算框架</p><p>本頁只提供計算方式, 不提供硬體, 電價與雲端 API 單價; 數字請填入查價當日的官方報價, 並註記查價日期.</p></div><h2 id="自架年成本" tabindex="-1">自架年成本 <a class="header-anchor" href="#自架年成本" aria-label="Permalink to &quot;自架年成本&quot;">​</a></h2><p>自架的花費多半在購置時與每週固定發生, 不太隨使用次數增減. 硬體購置價要分攤到預計使用的年數, 稱為攤提; 其他項目則以一年為單位估算.</p><table tabindex="0"><thead><tr><th>成本類別</th><th>公式</th><th>填入數字</th></tr></thead><tbody><tr><td>硬體攤提</td><td>購置價 ÷ 預計使用年數</td><td></td></tr><tr><td>電費</td><td>平均功耗 (kW) x 每日運轉小時 x 365 x 電價 (元/度)</td><td></td></tr><tr><td>維運人時</td><td>每週小時 x 52 x 時薪</td><td></td></tr><tr><td>備份與網路</td><td>外接硬碟, 雲端備份, 網路費用的年合計</td><td></td></tr><tr><td>汰換準備</td><td>零件故障或提早汰換的預留金</td><td></td></tr><tr><td><strong>合計 (年)</strong></td><td>上列加總</td><td></td></tr></tbody></table><h2 id="雲端-api-年成本" tabindex="-1">雲端 API 年成本 <a class="header-anchor" href="#雲端-api-年成本" aria-label="Permalink to &quot;雲端 API 年成本&quot;">​</a></h2><p>雲端 API 依用量收費, 計價單位是 token, 也就是模型處理文字時切出的小片段 (見 <a href="/lanai-handbook/know/k1-basics">K1</a>). 輸入與輸出分開計價, 下表的單價以每 100 萬 token 計.</p><table tabindex="0"><thead><tr><th>成本類別</th><th>公式</th><th>填入數字</th></tr></thead><tbody><tr><td>輸入 token 費用</td><td>每月輸入 token 數 ÷ 100 萬 x 輸入單價 x 12</td><td></td></tr><tr><td>輸出 token 費用</td><td>每月輸出 token 數 ÷ 100 萬 x 輸出單價 x 12</td><td></td></tr><tr><td>其他</td><td>向量嵌入, 檔案儲存等附加費用</td><td></td></tr><tr><td><strong>合計 (年)</strong></td><td>上列加總</td><td></td></tr></tbody></table><p>單價請從供應商官方定價頁取得並註記查價日. 每月 token 數可由現有使用紀錄推估; 沒有紀錄時, 先做 <a href="/lanai-handbook/decide/poc-30days">PoC</a> 累積一個月的實際用量.</p><h2 id="損益平衡" tabindex="-1">損益平衡 <a class="header-anchor" href="#損益平衡" aria-label="Permalink to &quot;損益平衡&quot;">​</a></h2><p>損益平衡是兩種做法年成本相同的那一點. 可以想成買車與叫車的比較: 每月里程越高, 買車越划算; 里程很低時, 車價與保養費攤下來反而比較貴.</p><p>自架合計 (年) ÷ 雲端合計 (年) 小於 1, 表示以目前用量, 自架的年成本較低. 此比值對用量很敏感: 用量減半, 雲端成本約減半, 而自架的硬體與人時大多不變.</p><h2 id="示意計算-數字純屬假設-非市場資料" tabindex="-1">示意計算 (數字純屬假設, 非市場資料) <a class="header-anchor" href="#示意計算-數字純屬假設-非市場資料" aria-label="Permalink to &quot;示意計算 (數字純屬假設, 非市場資料)&quot;">​</a></h2><p>假設購置價 100,000 元, 使用 3 年, 攤提約 33,333 元/年. 假設維運每週 2 小時, 時薪 500 元, 年維運人時 52,000 元. 此時即使不計電費, 自架年成本已約 85,333 元 (33,333 + 52,000). 雲端 API 的年費用低於這個金額時, 雲端較便宜.</p><p>此範例只示範算式. 實際的硬體價格, 時薪與用量因情況而異, 結論可能相反.</p><h2 id="常見遺漏" tabindex="-1">常見遺漏 <a class="header-anchor" href="#常見遺漏" aria-label="Permalink to &quot;常見遺漏&quot;">​</a></h2><ul><li>維運人時與假日, 休假時的代理人.</li><li>硬體閒置期間仍在攤提.</li><li>模型升級後可能需要更多記憶體, 使硬體提早不夠用.</li><li>雲端方案的企業折扣, 用量承諾與資料處理條款, 會改變雲端那一欄.</li></ul><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><p>本頁為整理者設計的成本試算框架. 公式 (硬體攤提, 電費, 維運人時, token 費用) 是一般的成本算式, 表格中的空欄由讀者填寫, 頁內沒有市場價格或統計資料.</p><ul><li><strong>雲端 API 依每百萬 token 計價, 輸入與輸出分開</strong>: 以 Anthropic (提供 Claude 模型雲端 API 的廠商) 的定價頁為例, 價格以「美元 / MTok」標示, 輸入與輸出各有單價; 其他供應商以其官方定價頁為準, 填寫時須註記查價日. <a href="https://platform.claude.com/docs/en/about-claude/pricing" target="_blank" rel="noreferrer">Anthropic: Pricing</a></li><li><strong>示意計算</strong>: 購置價 100,000 元, 使用 3 年, 每週維運 2 小時, 時薪 500 元, 皆為假設值. 算式為 100,000 ÷ 3 約 33,333 元, 2 x 52 x 500 = 52,000 元, 合計約 85,333 元; 這是算術結果, 不是市場資料.</li><li><strong>「維運人時多半估得偏低」</strong>: 整理者推論 (信心: 中), 無統計來源. 驗證方式是 <a href="/lanai-handbook/decide/poc-30days">30 天 PoC</a> 第 4 週記錄的實際工時.</li><li><strong>「用量減半, 雲端成本約減半」</strong>: 按量計價下的算術推論; 企業折扣或用量承諾會改變結果, 頁尾已列為常見遺漏.</li><li><strong>「常見遺漏」清單</strong>: 整理者列出的檢核事項 (推論), 不是引用自調查.</li><li>文中的類比 (買車與叫車): 整理者所寫, 無外部來源, 不應當作技術定義引用.</li></ul>',22)])])}const u=a(o,[["render",i]]);export{b as __pageData,u as default};
